<script setup lang="ts">
import {computed} from 'vue'
import type {Detail,EssayEvidence} from './records'
import {holisticReason} from './consensusDisplay'
const props=defineProps<{detail:Detail;interactive?:boolean}>(),emit=defineEmits<{locate:[box:EssayEvidence['location']]}>()
const sides=computed(()=>props.detail.result.dual_review?.results||{A:props.detail.result})
const rows=computed(()=>Object.entries(sides.value).flatMap(([side,model])=>(model?.sub_questions||[]).filter(q=>q.scoring_mode==='holistic').map(q=>({side,q,r:q.holistic_result}))))
const labels:Record<string,string>={met:'符合',partial:'部分符合',not_met:'未达到',uncertain:'待核对',clear:'未指出史实问题',issues:'有史实问题',violated:'违反设问限制'}
</script>
<template><section v-if="rows.length" aria-label="小论文分档双评"><h4>小论文分档双评建议</h4><p>整体分档不累计维度分；按评价项目给分时仅累计教师设置的项目。以下均为AI建议。</p><p v-for="c in detail.result.dual_review?.comparison?.holistic_comparisons||[]" :key="c.question_id">{{c.question_id}}：{{c.reasons.length?c.reasons.map(holisticReason).join('；'):'同档同分，关键判断一致'}}</p>
<article v-for="item in rows" :key="item.side+item.q.sub_question_id" class="point-record"><h5>{{item.q.sub_question_id}} · AI-{{item.side}} · {{item.r?.level_id||(item.r?.dimension_assessments?.some(d=>d.score!==undefined)?'按评价项目计分':'未定档')}} · {{item.q.suggested_total??'未获得有效分数'}} / {{item.q.max_total}}<span v-if="item.q.transcription?.review_only && item.q.suggested_total != null"> · 参考分</span></h5><details v-if="item.q.transcription"><summary>查看独立转写</summary><p v-if="item.q.transcription.status==='uncertain'">{{item.q.transcription.summary || '转写有待核对，请查看原图。'}}</p><p v-for="line in item.q.transcription.lines" :key="line.id">{{line.text}}</p></details><template v-if="item.r"><p v-if="item.q.blocked" role="status">结果需核对，不能直接采纳</p><p v-for="reason in item.q.block_reasons" :key="reason">{{reason}}</p><p v-if="!item.r.dimension_assessments?.some(d=>d.score!==undefined)">对应标准：{{item.q.holistic_source?.holistic?.levels?.find(l=>l.id===item.r?.level_id)?.description||'尚未确定'}}</p><ul><li v-for="d in item.r.dimension_assessments||[]" :key="d.dimension_id">{{item.q.holistic_source?.holistic?.dimension_definitions?.find(v=>v.id===d.dimension_id)?.label||d.dimension_id}}：{{labels[d.judgment]||d.judgment}} <strong v-if="d.score!==undefined">{{d.score}}分</strong> · {{d.reason}}</li></ul><p>主要依据：{{item.r.strengths?.join('；')||'未列出'}}</p><p>主要不足：{{item.r.weaknesses?.join('；')||'未列出'}}</p><p>史实核对：{{labels[item.r.factual_status]||item.r.factual_status}}；{{item.r.critical_factual_issues?.join('；')}}</p><p>设问限制：{{labels[item.r.constraint_status]||item.r.constraint_status}} · {{item.r.constraint_reason}}</p><details><summary>查看学生原文证据</summary><p v-for="e in item.q.holistic_evidence||item.r.evidence||[]" :key="e.id">{{e.student_quote}} <span v-if="!interactive">第{{e.location.photo_index}}页</span><button v-else type="button" @click="emit('locate',e.location)">定位第{{e.location.photo_index}}页证据</button></p></details></template></article></section></template>
